return ['domain'=>'tag-groups','plural-forms'=>'nplurals=1; plural=0;','language'=>'vi','project-id-version'=>'Tag Groups 2.1.2','pot-creation-date'=>'2026-06-15T12:41:40+00:00','po-revision-date'=>'2026-06-15 13:42+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['Tag Groups'=>'Nhóm Thẻ','https://wordpress.org/plugins/tag-groups/'=>'https://wordpress.org/plugins/tag-groups/','Tag Groups allows you to organize your WordPress taxonomy terms and show them in clouds, tabs, accordions, tables, lists and much more.'=>'Nhóm Thẻ cho phép bạn tổ chức các thuật ngữ taxonomy WordPress của mình và hiển thị chúng trong các đám mây, tab, accordion, bảng, danh sách và nhiều hơn nữa.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','Home'=>'Trang Chủ','Taxonomies'=>'Taxonomies','Front End'=>'Giao Diện Người Dùng','Back End'=>'Quản Trị','First Steps'=>'Bước Đầu Tiên','Setup Wizard'=>'Trình Hướng Dẫn Thiết Lập','Settings'=>'Cài Đặt','Tag Group Admin'=>'Quản Trị Nhóm Thẻ','The term has been removed from all groups.'=>'Thuật ngữ đã bị xóa khỏi tất cả các nhóm.','Edit this item inline'=>'Chỉnh sửa mục này trực tiếp','Quick&nbsp;Edit'=>'Chỉnh sửa Nhanh','Please <a %s>click here to run the migration routines</a> to make sure we have migrated all tags.'=>'Vui lòng <a %s>nhấn vào đây để chạy các quy trình di chuyển</a> để đảm bảo chúng tôi đã di chuyển tất cả các thẻ.','Your settings/groups and your terms have been exported. Please download the resulting files with right-click or ctrl-click:'=>'Cài đặt/nhóm của bạn và các thuật ngữ của bạn đã được xuất. Vui lòng tải xuống các tệp kết quả bằng cách nhấp chuột phải hoặc ctrl-click:','Writing of the exported settings failed.'=>'Việc ghi lại cài đặt xuất đã thất bại.','The groups have been sorted alphabetically.'=>'Các nhóm đã được sắp xếp theo thứ tự chữ cái.','The label cannot be empty.'=>'Nhãn không thể để trống.','A tag group with the label \'%s\' already exists, or the label has not changed. Please choose another one or go back.'=>'Một nhóm nhãn với nhãn \'%s\' đã tồn tại, hoặc nhãn chưa thay đổi. Vui lòng chọn nhãn khác hoặc quay lại.','A new tag group with the label \'%s\' has been created!'=>'Một nhóm nhãn mới với nhãn \'%s\' đã được tạo ra!','A tag group with the label \'%s\' already exists.'=>'Một nhóm nhãn với nhãn \'%s\' đã tồn tại.','The tag group with the label \'%s\' has been saved!'=>'Nhóm nhãn với nhãn \'%s\' đã được lưu!','A tag group with the id %1$s and the label \'%2$s\' has been deleted.'=>'Một nhóm nhãn với id %1$s và nhãn \'%2$s\' đã bị xóa.','Error uploading the file.'=>'Lỗi khi tải lên tệp.','Error reading the file.'=>'Lỗi khi đọc tệp.','Error parsing the file.'=>'Lỗi khi phân tích tệp.','date unknown'=>'ngày không xác định','Your settings and groups have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'Cài đặt và nhóm của bạn đã được nhập từ tệp %1$s (được tạo bằng phiên bản plugin %2$s vào %3$s).','%d option was added or changed.'=>'%d tùy chọn đã được thêm hoặc thay đổi.','Your terms have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'Các thuật ngữ của bạn đã được nhập từ tệp %1$s (được tạo bằng phiên bản plugin %2$s vào %3$s).','We processed %d term.'=>'Chúng tôi đã xử lý %d thuật ngữ.','We saved %d term.'=>'Chúng tôi đã lưu %d thuật ngữ.','The group info of %d term was updated.'=>'Thông tin nhóm của %d thuật ngữ đã được cập nhật.','Filters'=>'Bộ lọc','Gutenberg'=>'Gutenberg','Multilingual'=>'Đa ngôn ngữ','Shortcodes'=>'Mã ngắn','Themes and Appearance'=>'Chủ đề và Giao diện','remove'=>'xóa','(recommended)'=>'(đề xuất)','keep'=>'giữ','use unfiltered_html filter'=>'sử dụng bộ lọc unfiltered_html','First Aid'=>'Cấp cứu','REST API'=>'REST API','System Information'=>'Thông tin Hệ thống','Debugging'=>'Gỡ lỗi','Export/Import'=>'Xuất/Nhập','Reset'=>'Đặt lại','Licences'=>'Giấy phép','Transients'=>'Tạm thời','Database'=>'Cơ sở dữ liệu','Filesystem'=>'Hệ thống tệp','WP Object Cache'=>'Bộ nhớ WP O